use vstd::prelude::*;

verus! {

    // Given an input vector `arr` and an integer `elem`, produce a new vector
    // that interleaves `elem` before each element of `arr`.
    //
    // Ensures:
    //   1. The length of the result is exactly twice the length of `arr`.
    //   2. For every k < arr.len(), result[2*k] == elem and result[2*k+1] == arr[k].
    fn insert_before_each(arr: &Vec<i32>, elem: i32) -> (result: Vec<i32>)
        ensures
            // result.len() == 2 * arr.len()
            (result.len() as nat) == 2 * (arr.len() as nat),
            // for each original index k, result[2*k] = elem and result[2*k+1] = arr[k]
            forall |k: nat| (k < (arr.len() as nat) ==>
                result[2*k] == elem &&
                result[2*k + 1] == arr[k]
            ),
    {
        // Preallocate space for 2 * arr.len() elements
        let mut res: Vec<i32> = Vec::with_capacity(arr.len() * 2);
        // i will range from 0 up to arr.len()
        let mut i: usize = 0;
        while i < arr.len()
            invariant
                // i never exceeds the original array length
                i <= arr.len(),
                // at each step, we have pushed exactly 2*i elements
                (res.len() as nat) == 2 * (i as nat),
                // and those 2*i elements satisfy the interleaving property
                forall |k: nat| (k < (i as nat) ==>
                    res[2*k] == elem &&
                    res[2*k + 1] == arr[k]
                ),
            decreases arr.len() - i,
        {
            // append the interleaved elements for index i
            res.push(elem);
            res.push(arr[i]);
            i += 1;
        }
        // by the end, i == arr.len(), so res.len() == 2*arr.len()
        res
    }

} // end of verus! block

